mapper.select:
SELECT expense_stationCode AS station_code, MAX(expense_stationName) AS station_name, COALESCE(SUM(CAST(NULLIF(TRIM(expense_realamt), '') AS DECIMAL(20, 2))), 0) AS sales_amount, COUNT(*) AS order_count FROM expense_calendar_info WHERE expense_state = '10' AND del_flag = '0' AND expense_buyDate >= #{startDate} AND expense_buyDate < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND expense_tenant = #{tenant}
AND expense_stationCode = #{stationCode}
GROUP BY expense_stationCode ORDER BY sales_amount DESC

SELECT expense_d_gdcode AS sku, MAX(expense_d_commName) AS product_name, MAX(expense_d_commCodeName) AS category_name, COALESCE(SUM(CAST(NULLIF(TRIM(expense_d_realamt), '') AS DECIMAL(20, 2))), 0) AS sales_amount, COALESCE(SUM(CAST(NULLIF(TRIM(expense_d_qty), '') AS DECIMAL(20, 4))), 0) AS quantity FROM expense_calendar_details WHERE expense_d_state = '10' AND del_flag = '0' AND expense_d_buyDate >= #{startDate} AND expense_d_buyDate < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND expense_d_stationCode = #{stationCode}
GROUP BY expense_d_gdcode ORDER BY
quantity sales_amount
DESC LIMIT #{topN}
